 record Fixture(ObjectNode model,ObjectNode sources,ObjectNode vector,ObjectNode proof){SrppZeroTargetExitValidator.Context context(){sources.fields().forEachRemaining(e->vector.putObject(e.getKey()).put("sourceId",e.getKey()).put("validation","VERIFIED").put("coverage","COMPLETE").put("capturedAt",AT).put("sha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(e.getValue()))));return new SrppZeroTargetExitValidator.Context(model,sources,vector,7,DAY,HASH,OffsetDateTime.parse(AT),false);}BigDecimal floor(){return SrppZeroTargetExitValidator.completionFloor(context(),LOW,ORDINARY);}}
 static ObjectNode owner(String date){return F.objectNode().put("verified",true).put("coverage","COMPLETE").put("ownerUserId",7).put("tradingDate",date).put("policyBundleSha256",HASH).put("source_ref","SYNTHETIC_CANONICAL_FUTURE_SOURCE_ONLY");}
 static ObjectNode wrap(ObjectNode payload){return F.objectNode().put("source_ref","SYNTHETIC_RAW_MARKET_SOURCE_ONLY").put("sha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(payload))).set("payload",payload);}
 static ArrayNode candidates(){return candidates(DAY);}
 static ArrayNode candidates(String day){ArrayNode all=F.arrayNode();int price=10;for(String symbol:List.of("VOO","0050","00881")){ObjectNode row=all.addObject();row.set("source",wrap(F.objectNode().put("stock_code",symbol).put("trading_date",day).put("adjustment_basis","DISTRIBUTION_ADJUSTED_52_WEEK").put("price",price).put("low52",1).put("high52",100)));price+=30;row.put("capacity_twd",TOTAL);ObjectNode gates=row.putObject("gate_receipts");for(String gate:List.of("FX","BUY","SELL")){ObjectNode payload=F.objectNode().put("stock_code",symbol).put("trading_date",day).put("scope",gate).put("status","VERIFIED_PASS");payload.putArray("source_evidence").add(wrap(F.objectNode().put("provider","SYNTHETIC_ONLY").put("verified",true)));gates.set(gate,wrap(payload));}}return all;}
 static Fixture fixture()throws Exception{
  ObjectNode model=(ObjectNode)SrppDailyContextResponseValidator.parseStrict(MODEL_SEED.getBytes(java.nio.charset.StandardCharsets.UTF_8)),sources=F.objectNode(),state=owner(DAY);sources.set("zero-target-exit-state",state);sources.putObject("policy").put("rawModelBytes",SrppZeroTargetExitValidatorTest.M.writeValueAsString(model));ObjectNode proof=owner(DAY).put("scope","FULL_MANAGED_ROTATION_SUBSET_EXCLUDING_VOO_SGOV_24B2");state.set("rotationCompletion",proof);ObjectNode snap=proof.putObject("completionSnapshot").put("snapshotDate",DAY),assets=snap.putObject("assets"),saved=assets.putObject("snapshot").put("snapshotDate",DAY).put("id",99),live=assets.putObject("liveAssets").put("snapshotDate",DAY).put("snapshotId",99).put("liveTotalAssets",TOTAL.toPlainString());ArrayNode stocks=live.putArray("stocks"),original=saved.putArray("stocks");saved.putArray("funds");ObjectNode classes=snap.putObject("classifications"),stockClasses=classes.putObject("resolvedStockClasses");classes.putObject("resolvedFundClasses");ObjectNode authority=proof.putObject("targetAuthority").put("source_ref","policy").put("rawModelBytes",SrppZeroTargetExitValidatorTest.M.writeValueAsString(model));authority.put("marketCandidates",SrppZeroTargetExitValidatorTest.M.writeValueAsString(candidates()));
  ObjectNode selected=SrppCompletionReserveAllocation.selectMarketAdjustment(model,TOTAL,LocalDate.parse(DAY),SrppZeroTargetExitValidator.parse(authority.path("marketCandidates")));assertThat(selected.path("status").asText()).isEqualTo("ALLOCATION_REVIEW");assertThat(selected.path("selected_symbol").asText()).isEqualTo("VOO");Map<String,BigDecimal> additions=new TreeMap<>();selected.path("allocation_twd").fields().forEachRemaining(e->additions.put(e.getKey(),e.getValue().decimalValue()));var projection=SrppCompletionReserveAllocation.project(model,TOTAL,LocalDate.parse(DAY),null,additions);assertThat(projection.status()).isEqualTo("TARGETS_READY");
  long id=100;BigDecimal emergencyShares=projection.weights().get("emergency_00865B").multiply(TOTAL).divide(new BigDecimal("100"),0,RoundingMode.FLOOR);BigDecimal strategicShares=projection.weights().get("00865B").multiply(TOTAL).divide(new BigDecimal("100"),0,RoundingMode.FLOOR);
  for(var entry:projection.weights().entrySet()){String symbol=entry.getKey();if(Set.of("TWD_term_deposits","demand_deposits_and_cash","emergency_00865B").contains(symbol)||entry.getValue().signum()==0)continue;String market=Set.of("VOO","VT","SGOV").contains(symbol)?"美股":"台股";BigDecimal shares=entry.getValue().multiply(TOTAL).divide(new BigDecimal("100"),0,RoundingMode.FLOOR);if(symbol.equals("00865B"))shares=shares.add(emergencyShares);BigDecimal value=shares.multiply(new BigDecimal("100"));stocks.addObject().put("holdingId",id).put("stockCode",symbol).put("market",market).put("shares",shares.toPlainString()).put("liveValue",value.toPlainString());original.addObject().put("id",id).put("stockCode",symbol).put("market",market).put("brokerId",3).put("shares",shares.toPlainString());stockClasses.put(symbol+":"+market,Set.of("00865B","00719B","00697B","SGOV").contains(symbol)?"BOND":"STOCK");
   if(symbol.equals("00865B")){ObjectNode sub=owner(DAY);snap.set("subaccounts",sub);ArrayNode rows=sub.putArray("rows");for(String role:List.of("EMERGENCY_CATHAY","STRATEGIC_FUBON")){BigDecimal part=role.equals("EMERGENCY_CATHAY")?emergencyShares:strategicShares;rows.addObject().put("holdingId",id).put("brokerId",3).put("accountFingerprint",role+"_CANONICAL").put("symbol","00865B").put("market","台股").put("subaccount",role).put("shares",part.toPlainString()).put("valueTwd",part.multiply(new BigDecimal("100")).toPlainString()).put("source_ref","SYNTHETIC_CANONICAL_SUBACCOUNT_ONLY");}}id++;
  }
  return new Fixture(model,sources,F.objectNode(),proof);
 }
 @Test void completeRawD222TargetsAndReconciledEmergencySplitRestoreOrdinaryFloor()throws Exception{assertThat(fixture().floor()).isEqualByComparingTo(ORDINARY);}
 @Test void currentZeroTargetHoldingProvesIncompleteWithoutUnrelatedCandidateEvidence()throws Exception{var f=fixture();ObjectNode assets=(ObjectNode)f.proof.at("/completionSnapshot/assets");((ArrayNode)assets.at("/snapshot/stocks")).addObject().put("id",999).put("stockCode","2881").put("market","台股").put("shares","1");((ArrayNode)assets.at("/liveAssets/stocks")).addObject().put("holdingId",999).put("stockCode","2881").put("market","台股").put("shares","1").put("liveValue","100");((ObjectNode)f.proof.at("/completionSnapshot/classifications/resolvedStockClasses")).put("2881:台股","STOCK");((ObjectNode)f.proof.path("targetAuthority")).putNull("marketCandidates");assertThat(f.floor()).isEqualByComparingTo(LOW);((ObjectNode)f.proof.path("completionSnapshot")).put("snapshotDate","2027-11-25");assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}
 @Test void missingOrChangedActualAuthorityCannotClaimCompletion()throws Exception{for(String bad:List.of("source_ref","rawModelBytes","marketCandidates")){var f=fixture();ObjectNode a=(ObjectNode)f.proof.path("targetAuthority");if(bad.equals("marketCandidates"))a.putNull(bad);else a.put(bad,"FORGED");assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}}
 @Test void claimedCompletionOrToleranceIsNotAnAuthority()throws Exception{for(String key:List.of("completed","tolerance","typedTargetWeights")){var f=fixture();f.proof.put(key,true);assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}var f=fixture();((ObjectNode)f.model.path("simulation_contract")).put("transition_completion_tolerance_total_weight","1");assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}
 @Test void missingMixedEmergencySplitCannotTreatAll00865BAsStrategic()throws Exception{var f=fixture();((ObjectNode)f.proof.path("completionSnapshot")).remove("subaccounts");assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}
 @Test void sourceHashConsistentButGateRejectedCandidateCannotBeReplacedByTypedTargets()throws Exception{var f=fixture();ArrayNode candidates=(ArrayNode)SrppZeroTargetExitValidator.parse(f.proof.at("/targetAuthority/marketCandidates"));ObjectNode first=(ObjectNode)candidates.get(0);ObjectNode payload=((ObjectNode)first.at("/gate_receipts/BUY/payload")).deepCopy().put("status","VERIFIED_BLOCKED");((ObjectNode)first.path("gate_receipts")).set("BUY",wrap(payload));((ObjectNode)f.proof.path("targetAuthority")).put("marketCandidates",SrppZeroTargetExitValidatorTest.M.writeValueAsString(candidates));assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}

 @Test void splitMustReconcileExactHoldingRoleIdentityAndValue()throws Exception{for(String bad:List.of("broker","account","sum","role","owner","date","duplicate","holding")){var f=fixture();ObjectNode proof=(ObjectNode)f.proof.at("/completionSnapshot/subaccounts"),row=(ObjectNode)proof.path("rows").get(0);switch(bad){case "broker"->row.put("brokerId",9);case "account"->row.remove("accountFingerprint");case "sum"->row.put("valueTwd",new BigDecimal(row.path("valueTwd").asText()).add(BigDecimal.ONE).toPlainString());case "role"->row.put("subaccount","CALLER_CORE");case "owner"->proof.put("ownerUserId",8);case "date"->proof.put("tradingDate","2027-11-25");case "duplicate"->((ArrayNode)proof.path("rows")).add(row.deepCopy());default->row.put("holdingId",999999);}assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}}
 @Test void fullyReplayedHistoricalCompletionCanBeAStickyEvent()throws Exception{var f=fixture();((ObjectNode)f.proof.path("completionSnapshot")).put("snapshotDate","2027-11-25");((ObjectNode)f.proof.at("/completionSnapshot/assets/snapshot")).put("snapshotDate","2027-11-25");((ObjectNode)f.proof.at("/completionSnapshot/assets/liveAssets")).put("snapshotDate","2027-11-25");((ObjectNode)f.proof.at("/completionSnapshot/subaccounts")).put("tradingDate","2027-11-25");((ObjectNode)f.proof.path("targetAuthority")).put("marketCandidates",SrppZeroTargetExitValidatorTest.M.writeValueAsString(candidates("2027-11-25")));assertThat(f.floor()).isEqualByComparingTo(ORDINARY);}

 @Test void outerCurrentDateCannotRelabelHistoricalOrMissingL0DatesBeforeShortcut()throws Exception{for(String which:List.of("snapshot","liveAssets","both","missing")){var f=fixture();ObjectNode assets=(ObjectNode)f.proof.at("/completionSnapshot/assets");((ArrayNode)assets.at("/snapshot/stocks")).addObject().put("id",999).put("stockCode","2881").put("market","台股").put("shares","1");((ArrayNode)assets.at("/liveAssets/stocks")).addObject().put("holdingId",999).put("stockCode","2881").put("market","台股").put("shares","1").put("liveValue","100");((ObjectNode)f.proof.at("/completionSnapshot/classifications/resolvedStockClasses")).put("2881:台股","STOCK");if(which.equals("missing"))((ObjectNode)assets.path("liveAssets")).remove("snapshotDate");else{if(which.equals("snapshot")||which.equals("both"))((ObjectNode)assets.path("snapshot")).put("snapshotDate","2027-06-30");if(which.equals("liveAssets")||which.equals("both"))((ObjectNode)assets.path("liveAssets")).put("snapshotDate","2027-06-30");}assertThatThrownBy(f::floor).isInstanceOf(RuntimeException.class);}}
